const PRO={channelTab:'overview',channelId:'',competitorTab:'videos',settingsTab:'connections',settings:null,settingsBusy:false,cmpQuery:'',cmpSort:'views',cmpOnly:'all',cmpPage:0,toolState:new Map()};
const proLegacyChDash=chDash,proLegacyNav=nav,proLegacyToolOpen=toolOpen,proLegacyToolsv=toolsv,proLegacyFromHash=fromHash,proLegacyToolRun=toolRun;
const proHeading=(eyebrow,title,description,actions='')=>'<div class="pro-page-heading"><div><div class="studio-eyebrow">'+sx(eyebrow)+'</div><h1>'+sx(title)+'</h1><p>'+sx(description)+'</p></div><div class="pro-heading-actions">'+actions+'</div></div>';
function proTabs(id,items,current,action){return '<div class="pro-tabs" role="tablist" aria-label="'+sx(id)+'">'+items.map(([key,label])=>'<button type="button" role="tab" id="'+id+'-'+key+'" aria-selected="'+(key===current)+'" aria-controls="'+id+'-panel" tabindex="'+(key===current?'0':'-1')+'" onclick="'+action+'(\''+key+'\')" onkeydown="proTabKey(event)">'+sx(label)+'</button>').join('')+'</div>'}
function proTabKey(e){if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const list=[...e.currentTarget.parentElement.querySelectorAll('[role=tab]')],i=list.indexOf(e.currentTarget);const n=e.key==='Home'?0:e.key==='End'?list.length-1:(i+(e.key==='ArrowRight'?1:-1)+list.length)%list.length;const id=list[n].id;list[n].click();document.getElementById(id)?.focus()}
function proNotice(title,body){return '<details class="pro-method"><summary>'+sx(title)+'</summary><p>'+sx(body)+'</p></details>'}
function proScanSelect(kind,onchange){const scans=SCANS.filter(s=>!kind||s.kind===kind);return '<label class="pro-field">Saved '+(kind==='channel'?'channel':'scan')+'<select aria-label="Saved '+(kind||'analysis')+'" onchange="'+onchange+'"><option value="">Choose a saved scan</option>'+scans.map(s=>'<option value="'+sx(s.id)+'" '+(s.id===cur?'selected':'')+'>'+sx(s.ch?.name||s.topic)+' · '+sn(s.kept)+' videos</option>').join('')+'</select></label>'}
function proSource(d){return '<div class="pro-source"><span class="studio-chip">Saved analysis</span><span>'+sx(d.ts||'Timestamp unavailable')+'</span><span>'+sn(d.items?.length||0)+' measured videos</span><a href="/api/export?id='+encodeURIComponent(d.id)+'&fmt=csv" download>Export CSV</a></div>'}
nav=function(){proLegacyNav();const settings=$('#nav a[data-v="gen"]');if(settings){settings.dataset.v='settings';settings.href='#/settings';settings.innerHTML=ico('gear',16)+'Settings';settings.classList.toggle('on',view==='settings');settings.setAttribute('aria-current',view==='settings'?'page':'false');settings.onclick=e=>{e.preventDefault();go('settings')}}};
VW.settings={f:proSettings,t:'Settings',i:'gear'};
VW.gen.t='Generation reference';

async function proSettings(){const token=RTN;$('#main').innerHTML=proHeading('WORKSPACE CONFIGURATION','Settings','Manage connections, analysis preferences and workspace appearance.')+skelGrid(3);try{const r=await jp('/api/studio/tool',{kind:'settings'});if(token!==RTN)return;PRO.settings=r;proSettingsDraw()}catch(e){if(token===RTN)$('#main').innerHTML=proHeading('WORKSPACE CONFIGURATION','Settings','Configuration could not be loaded.')+'<div class="card"><p role="alert">'+sx(e.message)+'</p><button class="go" onclick="proSettings()">Retry</button></div>'}}
function proSettingsTab(tab){PRO.settingsTab=tab;proSettingsDraw()}
function proSettingsDraw(){const s=PRO.settings;if(!s)return;const tab=PRO.settingsTab;let h='';if(tab==='connections')h='<div class="pro-settings-intro"><h2>Your providers</h2><p>Configured means a key is stored. It does not guarantee that the provider will accept a request.</p></div><div class="pro-provider-grid">'+[['youtube','YouTube Data API','Public channel counts, video statistics, search and rankings.','1'],['gemini','Gemini','Text drafts, vision analysis and optional cloud OCR.','2'],['runware','Runware','Image generation using your chosen thumbnail workflow.','3']].map(([key,title,description,number])=>{const p=s.providers[key];return '<section class="card pro-provider"><div class="live-head"><span class="pro-provider-icon">'+number+'</span><span class="studio-chip '+(p.configured?'good':'')+'">'+(p.configured?'Configured':'Not configured')+'</span></div><h2>'+title+'</h2><p>'+description+'</p><dl><dt>Current configuration</dt><dd>'+sx(p.model||((p.keys||0)+' stored key'+(p.keys===1?'':'s')))+'</dd></dl><details><summary>'+(p.configured?'Update connection':'Add API key')+'</summary><form class="studio-form" onsubmit="event.preventDefault();proSaveProvider(\''+key+'\')"><label>API key<input id="pro-key-'+key+'" type="password" autocomplete="new-password" spellcheck="false" placeholder="Paste a new key"></label>'+(key!=='runware'?'<label>Save method<select id="pro-mode-'+key+'"><option value="add">Add to existing key pool</option><option value="replace">Replace stored key pool</option></select></label>':'')+'<button class="go" id="pro-save-'+key+'">Save connection</button><div id="pro-provider-result-'+key+'" role="status"></div></form></details></section>'}).join('')+'</div>'+proNotice('Where are my keys stored?','Keys use the existing ClickLab configuration files or environment variables. Saved keys are not displayed here. Empty fields leave existing keys unchanged. Environment-variable configuration may take precedence over saved files.');
 if(tab==='analysis')h='<div class="pro-two-col"><section class="card"><h2>Text recognition</h2><p class="sub">Choose where thumbnail text is read. This controls the existing OCR setting.</p><label class="pro-setting-row"><span><b>Use Gemini OCR</b><small>Cloud vision uses your Gemini key and provider quota. Turn off to use available local engines.</small></span><input id="pro-ocr" type="checkbox" '+(s.ocr_cloud?'checked':'')+' onchange="proOcr(this)"></label><p id="pro-ocr-status" role="status"></p></section><section class="card"><h2>Available engines</h2>'+table(['Engine','Status'],[['Image processing',s.engines.pillow?'Available':'Unavailable'],['Local OCR',s.engines.ocr?'Ready':s.engines.ocr_loading?'Loading':'Unavailable'],['Tesseract',s.engines.tesseract?'Available':'Unavailable'],['Face detection',s.engines.face_ready?'Ready':s.engines.face||'Unavailable'],['Statistical analysis',s.engines.sk?'Ready':s.engines.sk_loading?'Loading':'Unavailable']])+'</section></div><section class="card"><h2>Generation options</h2><p class="sub">Model, size, reference strength and text treatment remain in the thumbnail workspace where you use them.</p><div class="bar"><button class="go" onclick="go(\'ai\')">Open AI thumbnail studio</button><button onclick="go(\'gen\')">Historical generation reference</button></div></section>';
 if(tab==='workspace')h='<div class="pro-two-col"><section class="card"><h2>Display preferences</h2><label class="pro-field">Table density<select id="pro-density" onchange="proPreference(\'density\',this.value)"><option value="comfortable" '+(localStorage.getItem('cl_density')!=='compact'?'selected':'')+'>Comfortable</option><option value="compact" '+(localStorage.getItem('cl_density')==='compact'?'selected':'')+'>Compact</option></select></label><p class="sub">Saved in this browser. Applies to analysis tables and tool results.</p></section><section class="card"><h2>Data & history</h2><p class="sub">Your scans and observations are stored on this computer.</p><div class="pro-path">'+sx(s.storage)+'</div><div class="bar"><button onclick="go(\'act\')">Saved scans</button><button onclick="go(\'realtime\')">Tracking & export</button></div>'+proNotice('Backup guidance','Stop the local server before copying the complete output folder, or use SQLite online backup. Tracking pauses while the server is stopped; historical gaps are not backfilled.')+'</section></div>';
 $('#main').innerHTML=proHeading('WORKSPACE CONFIGURATION','Settings','Clear controls. Existing values stay in place until you save a change.')+proTabs('settings',[['connections','Connections'],['analysis','Analysis'],['workspace','Workspace']],tab,'proSettingsTab')+'<section id="settings-panel" role="tabpanel" aria-labelledby="settings-'+tab+'">'+h+'</section>';}
async function proSaveProvider(key){if(PRO.settingsBusy)return;const el=$('#pro-key-'+key),value=el.value.trim(),status=$('#pro-provider-result-'+key),button=$('#pro-save-'+key);if(!value){status.textContent='Enter a new key. Your existing connection has not changed.';el.focus();return}PRO.settingsBusy=true;button.disabled=true;button.textContent='Saving…';try{const endpoint={youtube:'ytkey',gemini:'gemkey',runware:'aikey'}[key];await jp('/api/'+endpoint,{key:value,add:$('#pro-mode-'+key)?.value==='add'});el.value='';PRO.settings=await jp('/api/studio/tool',{kind:'settings'});if(view==='settings')proSettingsDraw();toast('Connection saved. It will be used by the next request.','ok')}catch(e){status.textContent='Could not save: '+e.message}finally{PRO.settingsBusy=false;button.disabled=false;button.textContent='Save connection'}}
async function proOcr(el){const old=PRO.settings.ocr_cloud;el.disabled=true;try{const r=await jp('/api/ocrmode',{on:el.checked});PRO.settings.ocr_cloud=!!r.on;$('#pro-ocr-status').textContent='Preference saved.'}catch(e){el.checked=old;$('#pro-ocr-status').textContent='Could not save: '+e.message}finally{el.disabled=false}}
function proPreference(key,value){localStorage.setItem('cl_'+key,value);document.body.dataset.density=localStorage.getItem('cl_density')||'comfortable';toast('Display preference saved','ok')}
document.body.dataset.density=localStorage.getItem('cl_density')||'comfortable';

function proChannelTab(tab){PRO.channelTab=tab;chanv()}
function proChannelSections(d){const t=document.createElement('template');t.innerHTML=proLegacyChDash(d);const sections={};for(const e of t.content.children){const name=e.querySelector('h3')?.textContent||'';if(/Estimated earnings/.test(name))sections.earnings=e.outerHTML;if(/^\s*Niche/.test(name))sections.niche=e.outerHTML;if(/Upload routine/.test(name))sections.routine=e.outerHTML;if(/Speed of new/.test(name))sections.speed=e.outerHTML}return sections}
chanv=async function(){const token=RTN;$('#main').innerHTML=proHeading('CHANNEL RESEARCH','Channel analytics','Understand the channel, then inspect the videos behind its performance.')+skelKpi(4);try{const d=cur?(D&&D.id===cur?D:await ensureData()):null;if(token!==RTN)return;const c=d?.kind==='channel'?d.ch:null;if(c&&PRO.channelId!==d.id){PRO.channelId=d.id;PRO.channelTab='overview'}let h=proHeading('CHANNEL RESEARCH','Channel analytics','A focused view of your saved channel analysis. Fresh counters are available in Real Time.','<button onclick="go(\'realtime\')">'+ico('trend',15)+'Fresh public counts</button>')+'<section class="card pro-channel-find"><form onsubmit="event.preventDefault();goChan()"><label class="pro-field" for="cq">Find a channel<input id="cq" value="'+sx(CQ)+'" placeholder="Channel name, @handle or YouTube URL"></label><div class="bar"><button class="go" type="submit">Open channel</button><button type="button" onclick="chFindOnly()">Search names</button></div></form>'+proScanSelect('channel','openChan(this.value)')+'</section>';
 if(CHJ)h+='<section class="card" id="chout"><h2>Analysing channel</h2><div id="chp" role="status"></div></section>';
 if(CHC)h+=chCands();if(RDJ)h+=radarProg();if(RD)h+='<details class="pro-method"><summary>Niche discovery results</summary>'+radarTable()+'</details>';
 if(!c){h+=sempty('Choose a channel to begin','Open a saved channel or search above. A full scan reads the public listing and measures each selected video.');$('#main').innerHTML=h;if(CHJ)chPoll();return}
 const s=d.cst||{},tab=PRO.channelTab;h+='<section class="card pro-channel-identity"><div class="live-head"><div class="rt-identity"><div class="pro-avatar">'+sx((c.name||'C').slice(0,1))+'</div><div><h2>'+sx(c.name)+'</h2><p>'+sx(c.handle||c.id)+'</p></div></div><a class="btn" href="'+sx(c.url||'https://www.youtube.com/channel/'+c.id)+'" target="_blank" rel="noopener">Open on YouTube ↗</a></div>'+proSource(d)+'</section>'+proTabs('channel',[['overview','Overview'],['videos','Videos'],['patterns','Patterns'],['earnings','Earnings & assumptions']],tab,'proChannelTab');let body='';
 if(tab==='overview'){body='<div class="studio-metrics">'+smetric('Measured videos',sn(d.items?.length),'Saved scan coverage')+smetric('Subscribers',s.subs==null?'—':sn(s.subs),'As recorded in this scan')+smetric('Median views',sn(s.views_med),'Across measured videos')+smetric('Median views / day',sn(s.vpd_med),'Lifetime views ÷ age')+'</div><div class="pro-two-col"><section class="card"><h2>Publishing rhythm</h2>'+table(['Metric','Recorded value'],[['Uploads per week',sn(s.per_week)],['Uploads in last 30 days',sn(s.last30)],['Latest upload',s.last||'Unknown'],['Median gap',s.gap_med==null?'Unknown':s.gap_med+' days']])+'</section><section class="card"><h2>Where to go next</h2><button class="pro-action-row" onclick="proChannelTab(\'videos\')"><span><b>Inspect the content</b><small>Sort, filter and open the full video measurements.</small></span>→</button><button class="pro-action-row" onclick="proChannelTab(\'patterns\')"><span><b>Explore channel patterns</b><small>Upload timing, formats and observed topic signals.</small></span>→</button><button class="pro-action-row" onclick="go(\'cmp\')"><span><b>Compare the packaging</b><small>Inspect titles and thumbnails together.</small></span>→</button></section></div><section class="card"><div class="live-head"><h2>Most viewed in this scan</h2><button class="sm" onclick="proChannelTab(\'videos\')">View all videos</button></div>'+proVideoRows(d,5)+'</section>'+proNotice('Coverage and interpretation',d.cov||'Counts reflect this saved scan, not necessarily the complete channel. Views per day is a lifetime average. Patterns are observations, not causal findings.');}
 if(tab==='videos')body='<section class="pro-content-panel"><div class="pro-section-heading"><div><h2>Channel content</h2><p>Use the table filters to explore formats, dates and performance.</p></div><button onclick="go(\'deep\')">Deep analysis</button></div>'+stBlock()+'</section>';
 if(tab==='patterns'){const parts=proChannelSections(d);body=(parts.niche||'')+(parts.routine||'')+(parts.speed||'')+'<div class="bar"><button onclick="go(\'deep\')">Open statistical analysis</button><button onclick="go(\'ideas\')">Explore winning topics</button></div>';}
 if(tab==='earnings'){const parts=proChannelSections(d);body=snote('Public data cannot reveal actual revenue, watch time or monetization status. These are RPM-based scenarios; entering your own RPM still produces a calculation, not a verified revenue report.')+(parts.earnings||sempty('No earnings model in this scan','Run a current channel scan to build the comparison.'));body=body.replace('real calculation</b> (±15%, because every video’s RPM differs)','calculation using your supplied RPM</b> (actual revenue can differ)').replace('this is my real RPM','Save my RPM assumption');}
 $('#main').innerHTML=h+'<section id="channel-panel" role="tabpanel" aria-labelledby="channel-'+tab+'">'+body+'</section>';if(CHJ)chPoll();if(tab==='videos'){stWalk();stMetaHook()}proEnhanceLegacy($('#channel-panel'));}catch(e){if(token===RTN)$('#main').innerHTML=proHeading('CHANNEL RESEARCH','Channel analytics','The saved analysis could not be loaded.')+'<section class="card"><p role="alert">'+sx(e.message)+'</p><button onclick="chanv()">Retry</button></section>'}};
VW.ch.f=chanv;
function proVideoRows(d,limit=5){return '<div class="studio-scroll"><table class="studio-table"><thead><tr><th scope="col">Video</th><th scope="col">Views</th><th scope="col">Views / day</th><th scope="col">Details</th></tr></thead><tbody>'+d.items.map((it,i)=>({it,i})).sort((a,b)=>(b.it.views||0)-(a.it.views||0)).slice(0,limit).map(({it,i})=>'<tr><td><div class="pro-video-title"><img loading="lazy" src="'+imgu(it.thumb||'')+'" alt=""><span>'+sx(it.title)+'</span></div></td><td>'+sn(it.views)+'</td><td>'+sn(vpd(it))+'</td><td><button class="sm" onclick="zoom('+i+')" aria-label="Inspect '+sx(it.title)+'">Inspect</button></td></tr>').join('')+'</tbody></table></div>'}
function proEnhanceLegacy(root){if(!root)return;root.querySelectorAll('input:not([type=checkbox]),select,textarea').forEach(e=>{if(!e.labels?.length&&!e.hasAttribute('aria-label'))e.setAttribute('aria-label',e.placeholder||e.title||'Analysis filter')});root.querySelectorAll('table').forEach(t=>{if(!t.closest('.tp,.studio-scroll,.stscr')){const w=document.createElement('div');w.className='studio-scroll';t.before(w);w.append(t)}});root.querySelectorAll('.card>.sub').forEach(e=>{if(e.textContent.length>420){const details=document.createElement('details');details.className='pro-method';details.innerHTML='<summary>How to interpret this</summary>';e.before(details);details.append(e)}})}

function proCompetitorTab(tab){PRO.competitorTab=tab;cmp()}
function proCompetitorPick(id){cur=id;D=null;PRO.cmpPage=0;PRO.cmpQuery='';go('cmp')}
function proCompetitorForm(){return '<section class="card pro-channel-find"><form onsubmit="event.preventDefault();proStartScan()"><label class="pro-field" for="tq">Research a topic<input id="tq" placeholder="e.g. budget travel, Python tutorials" value="'+sx(TOPIC)+'"></label><div class="bar"><button type="submit" class="go">Scan competitors</button><details class="pro-inline-options"><summary>Scan options</summary><label>Videos<select id="pro-scan-n"><option value="12">12 · quick scan</option><option value="25" selected>25 · balanced</option><option value="50">50 · broader sample</option></select></label><label class="studio-check"><input type="checkbox" id="pro-scan-wide">Include related searches</label></details></div></form>'+proScanSelect('', 'proCompetitorPick(this.value)')+'</section>'}
async function proStartScan(){const q=$('#tq').value.trim();if(!q){$('#tq').focus();return toast('Enter a topic first','warn')}TOPIC=q;try{await runScan(q,Number($('#pro-scan-n').value),$('#pro-scan-wide').checked,true)}catch(e){toast(e.message,'bad');cmp()}}
cmp=async function(){const token=RTN;if(!cur){$('#main').innerHTML=proHeading('COMPETITIVE RESEARCH','Competitors','Find useful comparisons, inspect their packaging and build your next idea.')+proCompetitorForm()+sempty('Start with a topic','Scan a topic or open a saved analysis. Results use measured public data, with sources and limits.');return}if(!D||D.id!==cur)spin();try{const d=await ensureData();if(token!==RTN)return;if(!d){cur='';return cmp()}const W=winOf(d),tab=PRO.competitorTab;let h=proHeading(d.kind==='channel'?'CHANNEL PACKAGING':'COMPETITIVE RESEARCH',d.kind==='channel'?'Packaging analysis':'Competitors',d.kind==='channel'?'Compare the titles and thumbnails inside this channel.':'Inspect the videos behind a topic. Start with evidence, then explore patterns.')+proCompetitorForm()+'<section class="pro-analysis-title"><h2>'+sx(d.ch?.name||d.topic)+'</h2>'+proSource(d)+'</section><div class="studio-metrics">'+smetric('Measured videos',sn(d.items.length))+smetric('Breakouts',W.on?sn(W.win.length):'—','At least 2× sample median views/day')+smetric('Median views / day',sn(d.deep?.vpd_med),'Lifetime average, not daily traffic')+smetric('Median thumbnail score',sn(typeof medsc(d.items)==='number'?medsc(d.items):null),'Heuristic visual checks, not CTR')+'</div>'+proTabs('competitors',[['videos','Videos'],['table','Detailed table'],['patterns','Patterns'],['quality','Quality checks']],tab,'proCompetitorTab');let body='';
 if(tab==='videos')body='<div class="pro-results-controls"><label class="pro-search-label">Filter results<input id="pro-cmp-search" type="search" value="'+sx(PRO.cmpQuery)+'" placeholder="Search title or channel" oninput="PRO.cmpQuery=this.value;PRO.cmpPage=0;proCmpResults()"></label><label>Sort<select id="pro-cmp-sort" onchange="PRO.cmpSort=this.value;PRO.cmpPage=0;proCmpResults()">'+[['views','Most views'],['vpd','Views / day'],['score','Thumbnail score'],['new','Newest']].map(([v,l])=>'<option value="'+v+'" '+(PRO.cmpSort===v?'selected':'')+'>'+l+'</option>').join('')+'</select></label><label>Show<select onchange="PRO.cmpOnly=this.value;PRO.cmpPage=0;proCmpResults()"><option value="all" '+(PRO.cmpOnly==='all'?'selected':'')+'>All videos</option><option value="winners" '+(PRO.cmpOnly==='winners'?'selected':'')+'>Breakouts only</option></select></label><button onclick="PRO.competitorTab=\'table\';cmp()">Detailed table</button></div><div id="pro-cmp-results" aria-live="polite"></div>';
 if(tab==='table')body='<div class="bar"><button onclick="proCompetitorTab(\'videos\')">← Back to cards</button></div>'+stBlock();
 if(tab==='patterns')body='<div class="pro-section-heading"><div><h2>Patterns in this sample</h2><p>Observed associations, not promises of future performance.</p></div><button onclick="go(\'deep\')">Statistical analysis</button></div>'+stySec(d)+compSec(d)+radarOf(d);
 if(tab==='quality')body=issAgg(d.items)+proNotice('About thumbnail scores','Scores describe visual properties such as readability and contrast. They do not measure CTR. Use owner Studio data and controlled A/B experiments to evaluate click performance.')+'<button onclick="go(\'mine\')">Check my thumbnail</button>';
 $('#main').innerHTML=h+'<section id="competitors-panel" role="tabpanel" aria-labelledby="competitors-'+tab+'">'+body+'</section>';if(tab==='videos')proCmpResults();if(tab==='table'){if(d.kind==='channel')stWalk();stMetaHook()}proEnhanceLegacy($('#competitors-panel'));}catch(e){if(token===RTN)$('#main').innerHTML=proHeading('COMPETITIVE RESEARCH','Competitors','Could not load the saved analysis.')+'<div class="card"><p role="alert">'+sx(e.message)+'</p><button onclick="cmp()">Retry</button></div>'}};
VW.cmp.f=cmp;
function proCmpResults(){if(!D||!$('#pro-cmp-results'))return;const W=winOf(D),winnerIds=new Set((W.win||[]).map(v=>v.id));const q=PRO.cmpQuery.toLowerCase();let rows=D.items.map((it,i)=>({it,i})).filter(({it})=>[it.title,it.channel].join(' ').toLowerCase().includes(q)&&(PRO.cmpOnly!=='winners'||winnerIds.has(it.id)));rows.sort((a,b)=>PRO.cmpSort==='score'?(b.it.score??-1)-(a.it.score??-1):PRO.cmpSort==='vpd'?vpd(b.it)-vpd(a.it):PRO.cmpSort==='new'?(a.it.days??Infinity)-(b.it.days??Infinity):(b.it.views||0)-(a.it.views||0));const pages=Math.max(1,Math.ceil(rows.length/12));PRO.cmpPage=Math.min(PRO.cmpPage,pages-1);$('#pro-cmp-results').innerHTML='<div class="pro-results-meta">'+rows.length+' matching videos · page '+(PRO.cmpPage+1)+' of '+pages+'</div><div class="pro-competitor-grid">'+rows.slice(PRO.cmpPage*12,PRO.cmpPage*12+12).map(({it,i})=>'<article class="pro-video-card"><button class="pro-thumbnail" onclick="zoom('+i+')" aria-label="Inspect '+sx(it.title)+'"><img src="'+imgu(it.thumb||'')+'" alt="" loading="lazy">'+(winnerIds.has(it.id)?'<span class="pro-breakout">Breakout</span>':'')+'</button><div class="pro-video-card-body"><h3><a href="'+sx(it.url)+'" target="_blank" rel="noopener">'+sx(it.title)+'</a></h3><p>'+sx(it.channel||'Channel unavailable')+'</p><div class="pro-card-metrics"><span><b>'+sn(it.views)+'</b> views</span><span><b>'+sn(vpd(it))+'</b> / day</span><span><b>'+sn(it.score)+'</b> visual score</span></div><div class="pro-card-actions"><button class="go sm" onclick="zoom('+i+')">Inspect video</button><details><summary>More actions</summary><div class="pro-more-actions"><button onclick="regenAt('+i+')">Improve thumbnail</button><button onclick="aiAt('+i+')">Create AI thumbnail</button><button onclick="cbOpen('+i+')">Save to competitor bank</button><button onclick="gdpAt('+i+')">AI deep analysis</button><button onclick="cpLink(\''+sx(it.url)+'\')">Copy video link</button></div></details></div><div id="gdp'+i+'"></div></div></article>').join('')+'</div>'+(!rows.length?sempty('No matching videos','Change the search or switch back to all videos.'):'')+'<div class="pro-pagination"><button '+(PRO.cmpPage===0?'disabled':'')+' onclick="PRO.cmpPage--;proCmpResults()">Previous</button><span>Page '+(PRO.cmpPage+1)+' / '+pages+'</span><button '+(PRO.cmpPage>=pages-1?'disabled':'')+' onclick="PRO.cmpPage++;proCmpResults()">Next</button></div>'}

