function proCaptureTool(){const form=$('#studio-form');if(!form||!form.dataset.tool)return;const toolId=form.dataset.tool;if(toolId!==ST.tool)return;const inputs={};form.querySelectorAll('input:not([type=file]),textarea,select').forEach(e=>inputs[e.id]=e.value);PRO.toolState.set(ST.tool,{inputs,result:ST.result,comments:ST.comments,previews:ST.previews,image:ST.image})}
