function proToolRefine(id){const t=STUDIO_TOOLS.find(t=>t.id===id),q=$('#sf-q');if(q){q.placeholder=t.mode==='ai'?'Describe your audience, goal and tone. Paste any source material below.':t.mode==='compare'?'https://www.youtube.com/@channel-one\nhttps://www.youtube.com/@channel-two':['channel','channel-analysis','similar','outliers'].includes(t.mode)?'@channelhandle or https://www.youtube.com/channel/UC…':t.mode==='search'?'e.g. budget travel for students':id==='title-score'?'Enter the title you want to evaluate':id==='video-ids'?'Paste video URLs, one per line':'Paste a YouTube video or playlist URL';if(id==='video-ids')q.parentElement.firstChild.textContent='Video URLs, one per line';}const title=$('#main>h2');if(title){const heading=document.createElement('h1');heading.textContent=title.textContent;title.replaceWith(heading)}const crumb=$('#top .ttl');if(crumb)crumb.textContent='Creator tools / '+t.name;}
const proLegacyCopy={niche:['Niche research','Find candidate topics, then review the evidence behind them.'],deep:['Deep analysis','Explore measured relationships across the selected scan.'],ideas:['Winning topics & ideas','Turn observed winners into ideas for your next upload.'],ai:['AI thumbnail studio','Choose a scene, model and text treatment. Review the output before publishing.'],mine:['Thumbnail review','Inspect your image, understand weak points and compare improvements.'],hub:['Testing hub','Compare alternatives and record evidence for your next decision.'],own:['CTR & calibration','Use your own performance data to evaluate and calibrate visual scores.'],act:['Saved scans','Open an earlier analysis or check a scan in progress.'],hist:['Channel history','Compare recorded observations across time.'],cmpc:['Channel comparison','Review saved channel analyses side by side.'],bank:['Competitor bank','Keep useful references together for future research.'],gen:['Generation reference','Understand the available generation workflows and their tradeoffs.'],help:['Workspace guide','Learn how to research, create and interpret your results.']};
function proLegacyIntro(root){const copy=proLegacyCopy[view];if(!copy||root.querySelector('.pro-page-heading'))return;const title=root.querySelector(':scope>h2');if(title)title.remove();root.insertAdjacentHTML('afterbegin',proHeading('CLICKLAB WORKSPACE',copy[0],copy[1]));root.querySelectorAll(':scope>.sub').forEach(e=>{if(e.textContent.length>160){const guide=document.createElement('details');guide.className='pro-method';guide.innerHTML='<summary>Workflow guidance & interpretation</summary>';e.before(guide);guide.append(e)}});if(view==='ai'){let found=false;root.querySelectorAll(':scope>.card').forEach(card=>{if(card.querySelector('[onclick="aiKey()"],[onclick="gemKey()"],[onclick="ytKey()"]')){card.remove();found=true}});if(found)root.querySelector('.pro-page-heading').insertAdjacentHTML('afterend','<div class="pro-connection-strip"><span>Provider connections and OCR preferences are managed in Settings.</span><button onclick="go(\'settings\')">Manage connections</button></div>')}}
const proBaseEnhance=proEnhanceLegacy;proEnhanceLegacy=function(root){if(!root)return;proBaseEnhance(root);if(root.id==='main')proLegacyIntro(root)};
