const proIntroBase=proLegacyIntro;proLegacyIntro=function(root){proIntroBase(root);if(view!=='ai')return;for(const [id,title]of Object.entries({aiq:'Scene description',aiw:'Thumbnail text (optional)',air:'Reference image or video (optional)',aieng:'Image provider',aim:'Generation model',airz:'Output size',aimeth:'Creative direction'})){const el=document.getElementById(id);if(!el||el.closest('label'))continue;const label=document.createElement('label');label.className='pro-field pro-generation-field';label.htmlFor=id;label.textContent=title;el.before(label);label.append(el);el.setAttribute('aria-label',title)}const slider=$('#aistr');if(slider)slider.setAttribute('aria-label','Reference similarity');};
