const CW={channels:[],loaded:false,listPending:null,listVersion:0,active:cwStored('cl_active_workspace'),request:0,feedRequest:0,feed:null,feedError:'',homeMode:cwStored('cl_home_mode','feed'),research:'',researchType:'niche',editing:'',form:null,mutation:false,message:'',messageError:false,competitorQuery:'',relation:'direct',days:0,format:'all',profile:'',videoMode:'outliers',compare:null,compareKey:'',compareCache:new Map(),compareRequest:0,refreshing:false,refreshKey:'',compareError:''};
window.CL_ACTIVE_CHANNEL=CW.active;
const cwLimit=10;
