const cwCount=w=>w?Number(w.competitor_count??w.competitors?.length??0):0;
const cwValid=(token,route,request)=>token===RTN&&view===route&&request===CW.request;
async function cwApi(action,data={}){const r=await jp('/api/studio/workspace',{action,...data});if(r.error)throw Error(r.error);return r}
function cwActive(id){if(id&&!CW.channels.some(w=>w.id===id))return;const changed=CW.active!==id;CW.active=id;window.CL_ACTIVE_CHANNEL=id;cwStore('cl_active_workspace',id);if(changed){CW.profile='';CW.compare=null;CW.compareKey='';CW.compareError='';CW.competitorQuery='';CW.message='';CW.form=null;CW.editing='';window.dispatchEvent(new CustomEvent('cl-workspace-change',{detail:{id}}))}}
function cwReconcile(){if(!CW.channels.some(w=>w.id===CW.active))cwActive(CW.channels[0]?.id||'');else window.CL_ACTIVE_CHANNEL=CW.active}
async function cwList(force=false){if(CW.loaded&&!force)return CW.channels;if(CW.listPending&&!force)return CW.listPending;const version=++CW.listVersion;const work=(async()=>{const r=await cwApi('list');if(version===CW.listVersion){CW.channels=Array.isArray(r.channels)?r.channels:[];CW.loaded=true;cwReconcile()}return CW.channels})();CW.listPending=work;try{return await work}finally{if(CW.listPending===work)CW.listPending=null}}
function cwUpsert(workspace){if(!workspace?.id)throw Error('The server did not return a saved workspace.');const i=CW.channels.findIndex(w=>w.id===workspace.id);if(i<0)CW.channels.push(workspace);else CW.channels[i]=workspace;CW.listVersion++;CW.loaded=true;for(const key of CW.compareCache.keys())if(key.startsWith(workspace.id+'|'))CW.compareCache.delete(key);if(CW.active===workspace.id){CW.compare=null;CW.compareKey=''}CW.feed=null}
function cwSelect(id){if(CW.mutation)return;proCaptureTool();cwActive(id);render()}
function cwOptions(){return '<option value="" '+(CW.channels.length?'disabled':'')+'>'+ (CW.channels.length?'Choose your channel':'No channel workspaces yet')+'</option>'+CW.channels.map(w=>'<option value="'+sx(w.id)+'" '+(w.id===CW.active?'selected':'')+'>'+sx(w.name)+'</option>').join('')}
function cwSelector(label='Your channel workspace'){return '<label class="pro-field cw-selector">'+sx(label)+'<select onchange="cwSelect(this.value)" '+(CW.mutation?'disabled':'')+'>'+cwOptions()+'</select></label>'}
function cwSafeImage(value){const url=String(value||'');if(/^https?:\/\//i.test(url)||/^\/api\//.test(url))return url;return ''}
function cwAvatar(channel,name){const src=cwSafeImage(channel?.avatar);return src?'<img class="cw-avatar" src="'+sx(src)+'" alt="" loading="lazy">':'<span class="cw-avatar cw-initial" aria-hidden="true">'+sx((name||'C').slice(0,1))+'</span>'}
function cwTimestamp(value){if(value==null||value==='')return 'No cached reading';const d=new Date(typeof value==='number'?value*1000:value);return Number.isFinite(d.getTime())?d.toLocaleString():'Timestamp unavailable'}
function cwAge(value){if(value==null||value==='')return '';const d=new Date(typeof value==='number'?value*1000:value),age=Date.now()-d.getTime();if(!Number.isFinite(age))return '';if(age<3600000)return 'less than 1 hour old';if(age<86400000)return Math.floor(age/3600000)+' hours old';return Math.floor(age/86400000)+' days old'}
