function cwNavLink(id,label='',icon=''){const entry=VW[id];if(!entry)return '';const safeIcon=icon||({home:'layers',channels:'bars',compare:'layers',realtime:'trend',tools:'layers',settings:'gear',help:'help',mine:'image',ai:'image',hub:'layers',tl:'pen',ab:'layers',own:'trend',gen:'gear',bank:'layers',deep:'bars',hist:'trend',act:'layers'})[id]||'search';return '<a href="#/'+id+'" data-v="'+id+'" class="'+(view===id?'on':'')+'" '+(view===id?'aria-current="page"':'')+'>'+ico(safeIcon,16)+'<span>'+sx(label||entry.t)+'</span></a>'}
