nav=function(){const primary=['home','channels','compare','realtime','tools'],groups=[['Find an idea',['ideas','ch','niche','fun']],['Study & compare',['cmp','deep','cmpc']],['Your research',['act','hist','bank']],['Create & test',['mine','ai','tl','ab','hub','own']],['Advanced',['gen']]],known=new Set([...primary,'settings','help',...groups.flatMap(g=>g[1])]);const extra=Object.keys(VW).filter(id=>!known.has(id));if(extra.length)groups.push(['More features',extra]);$('#nav').innerHTML='<div class="brand"><span class="mk">C</span>ClickLab<button type="button" class="iconbtn gh cw-nav-hide" onclick="navTog()" aria-label="Hide sidebar">'+ico('menu',15)+'</button></div><div class="cw-nav-primary">'+primary.map(id=>cwNavLink(id)).join('')+'</div>'+groups.map(([title,ids])=>cwNavGroup(title,ids)).join('')+'<details class="nav-context"><summary>Saved scan context</summary><label class="pro-field">Channel scan<select id="csel" aria-label="Saved channel scan"><option value="">Choose a saved channel scan</option>'+SCANS.filter(s=>s.kind==='channel').map(s=>'<option value="'+sx(s.id)+'" '+(s.id===cur?'selected':'')+'>'+sx(s.ch?.name||s.topic)+'</option>').join('')+'</select></label><label class="pro-field">Topic scan<select id="sel" aria-label="Saved topic scan"><option value="">Choose a saved topic scan</option>'+SCANS.filter(s=>s.kind==='topic').map(s=>'<option value="'+sx(s.id)+'" '+(s.id===cur?'selected':'')+'>'+sx(s.topic)+'</option>').join('')+'</select></label><button class="sm" onclick="goNewChan()">New channel scan</button></details><div class="navfoot">'+cwNavLink('settings')+cwNavLink('help')+'<div class="cw-local-note">Local workspace · public evidence</div></div>';$('#nav').querySelectorAll('a[data-v]').forEach(a=>a.onclick=e=>{e.preventDefault();document.body.classList.remove('studio-menu');go(a.dataset.v)});$('#nav').querySelectorAll('.cw-nav-group').forEach(el=>el.addEventListener('toggle',()=>cwStore('cl_nav_group_'+el.dataset.group,el.open?'open':'closed')));$('#csel').onchange=e=>{cur=e.target.value;D=null;go('ch')};$('#sel').onchange=e=>{cur=e.target.value;D=null;go('cmp')}};
