topbar=function(){const workspace=cwCurrent();$('#top').innerHTML='<button type="button" class="iconbtn gh cw-header-menu" onclick="cwMenu()" aria-label="Toggle navigation" aria-expanded="'+(!document.body.classList.contains('navoff')&&(!matchMedia('(max-width:650px)').matches||document.body.classList.contains('studio-menu')))+'">'+ico('menu',18)+'</button><span class="ttl">ClickLab <span class="cw-crumb-divider">/</span> <b>'+sx(VW[view]?.t||'Dashboard')+'</b></span><span class="sp"></span>'+(CW.channels.length?'<label class="cw-header-workspace"><span class="cw-sr-only">Active channel workspace</span><select aria-label="Active channel workspace" onchange="cwSelect(this.value)" '+(CW.mutation?'disabled':'')+'>'+cwOptions()+'</select></label>':'')+'<button class="sm gh cw-global-search" onclick="palette()" aria-label="Search all ClickLab features">'+ico('search',15)+'<span>Search anything</span><kbd>Ctrl K</kbd></button><button class="iconbtn gh" onclick="go(\'settings\')" aria-label="Settings">'+ico('gear',17)+'</button><button class="go sm cw-header-action" onclick="go(\'channels\')">'+(workspace?'My channels':'Add your channel')+'</button>'};

function cwHomeMode(mode){CW.homeMode=mode;cwStore('cl_home_mode',mode);cwHomeDraw()}
function cwHomeShell(){return '<div class="cw-feed-toolbar"><div class="cw-mode-toggle" role="group" aria-label="Dashboard mode"><button type="button" aria-pressed="'+(CW.homeMode==='simple')+'" onclick="cwHomeMode(\'simple\')">Simple Start</button><button type="button" aria-pressed="'+(CW.homeMode!=='simple')+'" onclick="cwHomeMode(\'feed\')">Research Feed</button></div><span class="cw-local-status">'+ico('layers',13)+'Cached local evidence · refresh is your choice</span></div><section class="cw-welcome"><div class="studio-eyebrow">YOUR RESEARCH, IN FOCUS</div><h1>Welcome back.<br><span>Find your next move.</span></h1><p>Outliers worth studying. Channels worth watching. Ideas grounded in public evidence.</p><div class="cw-hero-mark" aria-hidden="true">'+ico('trend',76)+'</div></section><form class="cw-research-bar" onsubmit="event.preventDefault();cwResearch()"><label class="cw-research-input">'+ico('search',18)+'<span class="cw-sr-only">Research query</span><input type="search" id="cw-research" value="'+sx(CW.research)+'" oninput="CW.research=this.value" placeholder="Search a niche, channel, keyword or YouTube link" required></label><label class="cw-research-type"><span class="cw-sr-only">Research type</span><select id="cw-research-type" onchange="CW.researchType=this.value">'+[['niche','Niches'],['ch','Channels'],['keywords','Keywords'],['outliers','Outlier videos'],['topic','Topics']].map(([id,label])=>'<option value="'+id+'" '+(id===CW.researchType?'selected':'')+'>'+label+'</option>').join('')+'</select></label><button class="go" type="submit">Research '+ico('search',15)+'</button></form><p class="cw-search-note">Opens your chosen research tool. Public API requests run only when you submit the tool.</p>'}
function cwResearch(){const q=($('#cw-research')?.value||CW.research).trim();if(!q)return;CW.research=q;const type=CW.researchType;if(type==='ch'){CQ=q;go('ch');return}go('tools');toolOpen(type);const field=$('#sf-q');if(field){field.value=q;field.focus();proCaptureTool()}}
homev=async function(){const token=RTN,request=++CW.feedRequest;$('#main').innerHTML=cwHomeShell()+'<div id="cw-feed" aria-busy="true">'+skelGrid(3)+'</div>';CW.feedError='';const list=cwList().catch(e=>{if(token===RTN&&request===CW.feedRequest)CW.feedError='Channel workspaces could not be loaded: '+e.message});try{const r=await cwApi('feed');if(token!==RTN||request!==CW.feedRequest||view!=='home')return;CW.feed=r}catch(e){if(token===RTN&&request===CW.feedRequest)CW.feedError=e.message}await list;if(token===RTN&&request===CW.feedRequest&&view==='home'){nav();topbar();cwHomeDraw()}};
function cwHomeDraw(){if(view!=='home')return;const r=CW.feed;$('#main').innerHTML=cwHomeShell()+'<section id="cw-feed" aria-live="polite">'+(CW.feedError?'<div class="card"><p role="alert">'+sx(CW.feedError)+'</p><button onclick="homev()">Retry cached dashboard</button></div>':'')+(r?'<div class="cw-action-grid">'+[['channels','My channels',r.workspaces,'bars'],['realtime','Watchlist',r.tracked,'trend'],['cw-alerts','Outlier alerts',r.alerts?.length,'trend'],['tools','Creator tools',r.tools,'layers']].map(([id,label,count,icon])=>'<button class="cw-status-tile" '+(id==='cw-alerts'?'onclick="cwShowAlerts()"':'onclick="go(\''+id+'\')"')+'><span>'+sx(label)+' <b>· '+sn(count)+'</b></span>'+ico(icon,15)+'</button>').join('')+'</div>':'')+(CW.homeMode==='simple'?'<div class="cw-start-grid">'+[['channels','01','Set your channel context','Create a channel workspace, with or without a YouTube link.'],['compare','02','Build your comparison set','Keep up to 10 competitors for each of your own channels.'],['tools','03','Turn research into a draft','Use the existing research, writing, thumbnail and local tools.']].map(([route,number,title,body])=>'<button class="tool-tile" onclick="go(\''+route+'\')"><span class="studio-eyebrow">'+number+'</span><h3>'+title+'</h3><p>'+body+'</p></button>').join('')+'</div>':'')+'<div class="pro-section-heading cw-outlier-heading"><div><h2>Outliers to investigate</h2><p>Public video performance with the baseline in view.</p></div><button class="sm gh" onclick="go(\'compare\')">Explore competitors '+ico('trend',14)+'</button></div>'+(r?cwVideoCards(r.outliers||[]):sempty('Cached feed is unavailable','Retry the dashboard when the local workspace endpoint is ready.'))+'<section id="cw-alerts" class="cw-alert-section"><div class="pro-section-heading"><div><h2>Outlier alerts</h2><p>Observed videos at least 5× their recorded baseline.</p></div></div>'+(r?.alerts?.length?'<div class="cw-alert-list">'+r.alerts.map(v=>'<a class="cw-alert" href="https://www.youtube.com/watch?v='+encodeURIComponent(v.id)+'" target="_blank" rel="noopener"><b>'+sn(v.multiplier)+'×</b><span>'+sx(v.title)+'<small>'+sx(cwVideoChannel(v))+' · '+sn(v.views)+' views · '+sn(v.baseline_n)+' baseline videos</small></span></a>').join('')+'</div>':'<p class="studio-muted">'+(r?'No recorded 5× outlier alerts.':'Alerts unavailable until the cached feed loads.')+'</p>')+'</section><p class="cw-source-note">'+sx(r?.source||'Local cached workspace')+' · No private Studio traffic or automatic cloud AI.</p></section>'}
function cwShowAlerts(){if(view==='home'){const e=$('#cw-alerts');e?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'});if(e){e.setAttribute('tabindex','-1');e.focus({preventScroll:true})}}}
function cwVideoChannel(v){return typeof v.channel==='object'?(v.channel?.name||v.channel_id||'Channel unavailable'):(v.channel||v.channel_name||v.source_channel?.name||v.channel_id||'Channel unavailable')}
function cwVideoCards(rows){if(!rows.length)return sempty('No cached videos for this view','Add competitors, then explicitly refresh public data in Competitors. Missing data is never filled with estimates.');return '<div class="cw-video-grid">'+rows.map(v=>{const image=cwSafeImage(v.thumbnail||v.thumb),baseline=v.baseline_views??v.baseline,n=v.baseline_n,valid=typeof n==='number'&&n>0;return '<article class="cw-video-card"><a class="cw-video-image" href="https://www.youtube.com/watch?v='+encodeURIComponent(v.id)+'" target="_blank" rel="noopener" aria-label="Open video: '+sx(v.title)+'">'+(image?'<img loading="lazy" src="'+sx(image)+'" alt="">':'<span class="cw-missing-image">Thumbnail unavailable</span>')+(v.seconds!=null?'<span class="cw-duration">'+sx(cwDuration(v.seconds))+'</span>':'')+'</a><div class="cw-video-body"><h3><a href="https://www.youtube.com/watch?v='+encodeURIComponent(v.id)+'" target="_blank" rel="noopener">'+sx(v.title)+'</a></h3><p>'+sx(cwVideoChannel(v))+'</p><div class="cw-video-metrics"><div class="cw-multiplier"><strong>'+sn(v.multiplier)+(v.multiplier==null?'':'×')+'</strong><span>vs baseline</span></div><div><strong>'+sn(v.views)+'</strong><span>Total views</span></div><div><strong>'+sn(baseline)+'</strong><span>Baseline views</span></div></div><div class="cw-confidence"><span>'+sx(v.confidence||(valid?(n<10?'Small baseline sample':'Sample-backed baseline'):'Baseline unavailable'))+'</span><small>'+sn(n)+' baseline videos</small></div></div></article>'}).join('')+'</div>'}
function cwDuration(seconds){const s=Math.max(0,Math.floor(Number(seconds)||0));return s>=3600?Math.floor(s/3600)+':'+String(Math.floor(s/60)%60).padStart(2,'0')+':'+String(s%60).padStart(2,'0'):Math.floor(s/60)+':'+String(s%60).padStart(2,'0')}

