function cwNew(){if(CW.mutation)return;CW.editing='';CW.form={name:'',niche:'',language:'',country:'',q:''};CW.message='';cwChannelsDraw();$('#cw-name')?.focus()}
function cwEdit(){if(CW.mutation)return;const w=cwCurrent();if(!w)return;CW.editing=w.id;CW.form={name:w.name||'',niche:w.niche||'',language:w.language||'',country:w.country||'',q:''};CW.message='';cwChannelsDraw();$('#cw-name')?.focus()}
function cwForm(){const f=CW.form||(CW.form={name:'',niche:'',language:'',country:'',q:''});return '<section class="card cw-workspace-form"><h2>'+ (CW.editing?'Edit channel workspace':'Create your channel workspace')+'</h2><p class="studio-muted">Choose the name yourself. A draft workspace needs no YouTube link or API key.</p><form id="cw-workspace-form" class="studio-form" onsubmit="event.preventDefault();cwSaveWorkspace()"><label for="cw-name">Channel workspace name<input id="cw-name" name="name" value="'+sx(f.name)+'" maxlength="120" required oninput="CW.form.name=this.value" '+(CW.mutation?'disabled':'')+'></label><div class="cw-form-grid">'+[['niche','Niche / audience','e.g. educational tutorials'],['language','Language (optional)','Language or language code'],['country','Country (optional)','Country or country code']].map(([key,label,placeholder])=>'<label for="cw-'+key+'">'+label+'<input id="cw-'+key+'" name="'+key+'" value="'+sx(f[key])+'" placeholder="'+placeholder+'" maxlength="120" oninput="CW.form.'+key+'=this.value" '+(CW.mutation?'disabled':'')+'></label>').join('')+'</div><label for="cw-link">'+(CW.editing?'Link or replace YouTube channel (optional)':'YouTube channel link (optional)')+'<input id="cw-link" name="q" value="'+sx(f.q)+'" placeholder="@handle, YouTube channel URL or UC ID" oninput="CW.form.q=this.value" '+(CW.mutation?'disabled':'')+'></label><p class="pro-input-help">'+(CW.editing?'Leave the link blank to keep the existing connection. ':'')+'Providing a link may resolve public channel data on save. It does not start tracking or cloud AI.</p><div class="bar"><button class="go" type="submit" '+(CW.mutation?'disabled':'')+'>'+(CW.mutation?'Saving…':CW.editing?'Save changes':'Create workspace')+'</button>'+(CW.editing?'<button type="button" onclick="cwNew()" '+(CW.mutation?'disabled':'')+'>Cancel edit</button>':'')+'</div></form></section>'}
function cwChannelsDraw(){if(view!=='channels')return;const w=cwCurrent();$('#main').innerHTML=proHeading('YOUR CREATOR WORKSPACES','My channels','Keep your own channels, competitor sets and source context separate.','<button onclick="cwNew()" '+(CW.mutation?'disabled':'')+'>New workspace</button>')+cwSelector()+'<div class="cw-channel-list">'+CW.channels.map(channel=>'<button class="cw-channel-choice '+(channel.id===CW.active?'active':'')+'" data-workspace="'+sx(channel.id)+'" onclick="cwSelect(this.dataset.workspace)" aria-pressed="'+(channel.id===CW.active)+'" '+(CW.mutation?'disabled':'')+'>'+cwAvatar(channel.channel,channel.name)+'<span><b>'+sx(channel.name)+'</b><small>'+sx(channel.niche||'Niche not set')+' · '+cwCount(channel)+' / '+cwLimit+' competitors</small></span></button>').join('')+'</div>'+(CW.message?'<div class="cw-message '+(CW.messageError?'error':'')+'" role="'+(CW.messageError?'alert':'status')+'">'+sx(CW.message)+'</div>':'')+(w?'<section class="card cw-channel-summary"><div class="live-head"><div class="rt-identity">'+cwAvatar(w.channel,w.name)+'<div><h2>'+sx(w.name)+'</h2><p>'+sx([w.niche,w.language,w.country].filter(Boolean).join(' · ')||'Add audience details to this workspace')+'</p></div></div><div class="bar"><button onclick="cwEdit()" '+(CW.mutation?'disabled':'')+'>Edit workspace</button><button class="go" onclick="go(\'compare\')">Compare channels</button></div></div><p class="cw-source-note">'+(w.youtube_id?'Linked YouTube channel: '+sx(w.channel?.name||w.youtube_id)+' · Cached public data only.':'Draft workspace · no linked YouTube channel. Owner metrics are unavailable; competitors can still be compared.')+'</p></section>'+cwCompetitors(w):sempty('Create your first channel workspace','Use the form below. You can link your YouTube channel later.'))+cwForm()}
function cwCompetitors(w){const count=cwCount(w),full=count>=cwLimit;return '<section class="card cw-competitors"><div class="pro-section-heading"><div><h2>Competitors for '+sx(w.name)+'</h2><p>Each workspace keeps its own comparison set.</p></div><span class="studio-chip '+(full?'':'good')+'">'+count+' / '+cwLimit+' competitors</span></div><div class="cw-rival-list">'+(w.competitors||[]).map(c=>'<div class="cw-rival">'+cwAvatar(c.channel,c.channel?.name)+'<div><b>'+sx(c.channel?.name||c.id)+'</b><small>'+sx(cwRole(c.relation))+' · '+sn(c.channel?.subscribers)+' public subscribers</small></div><button class="sm" data-rival="'+sx(c.id)+'" onclick="cwRemoveCompetitor(this.dataset.rival)" aria-label="Remove '+sx(c.channel?.name||c.id)+' from this workspace" '+(CW.mutation?'disabled':'')+'>Remove</button></div>').join('')+(!count?'<p class="studio-muted">No competitors added to this workspace yet.</p>':'')+'</div><form class="cw-add-rival" onsubmit="event.preventDefault();cwAddCompetitor()"><label class="pro-field">YouTube competitor<input id="cw-competitor" value="'+sx(CW.competitorQuery)+'" oninput="CW.competitorQuery=this.value" placeholder="@handle, channel URL or UC ID" required '+(full||CW.mutation?'disabled':'')+'></label><label class="pro-field">Relationship<select id="cw-relation" onchange="CW.relation=this.value" '+(full||CW.mutation?'disabled':'')+'>'+[['direct','Direct competitor'],['format','Format reference'],['aspirational','Aspirational']].map(([id,label])=>'<option value="'+id+'" '+(CW.relation===id?'selected':'')+'>'+label+'</option>').join('')+'</select></label><button class="go" type="submit" '+(full||CW.mutation?'disabled':'')+'>'+(CW.mutation?'Saving…':'Add competitor')+'</button></form><p class="pro-input-help">'+(full?'This workspace is full. Remove a mapping to add another competitor.':'Add one channel at a time. Adding resolves public channel data; comparison refresh is separate.')+' Removing a competitor only removes this workspace’s mapping, not shared channel data.</p></section>'}
async function cwMutate(action,data,onSuccess){if(CW.mutation)return;CW.mutation=true;CW.message='';CW.messageError=false;nav();topbar();cwChannelsDraw();try{const r=await cwApi(action,data);if(r.workspace)cwUpsert(r.workspace);else{if(action==='remove-competitor'){const workspace=CW.channels.find(w=>w.id===data.id);if(workspace)cwUpsert({...workspace,competitors:(workspace.competitors||[]).filter(c=>c.id!==data.competitor_id),competitor_count:Math.max(0,cwCount(workspace)-1)})}await cwList(true)}onSuccess?.(r);CW.message=action==='remove-competitor'?'Competitor removed from this workspace.':action==='add-competitor'?'Competitor added. Refresh in Competitors when you want new public data.':'Channel workspace saved.'}catch(e){CW.messageError=true;CW.message='Could not save: '+e.message+'. Existing data is preserved.'}finally{CW.mutation=false;nav();topbar();if(view==='channels')cwChannelsDraw();else if(view==='compare')cwCompare()}}
async function cwSaveWorkspace(){const f=CW.form;if(!f||!f.name.trim()){$('#cw-name')?.focus();return}const id=CW.editing;const data={name:f.name.trim(),niche:f.niche.trim(),language:f.language.trim(),country:f.country.trim()};if(f.q.trim())data.q=f.q.trim();if(id)data.id=id;await cwMutate(id?'update':'create',data,r=>{if(!id&&r.workspace)cwActive(r.workspace.id);CW.form=null;CW.editing=''})}
async function cwAddCompetitor(){const w=cwCurrent(),q=CW.competitorQuery.trim();if(!w||!q){$('#cw-competitor')?.focus();return}if(cwCount(w)>=cwLimit)return;const id=w.id;await cwMutate('add-competitor',{id,q,relation:CW.relation},()=>{if(CW.active===id)CW.competitorQuery=''})}
async function cwRemoveCompetitor(competitor_id){const w=cwCurrent();if(!w)return;await cwMutate('remove-competitor',{id:w.id,competitor_id})}

function cwComparisonKey(id=CW.active){return id+'|'+CW.days+'|'+CW.format}
function cwCompareControls(){const w=cwCurrent(),key=cwComparisonKey();return '<section class="card cw-compare-controls">'+cwSelector()+'<label class="pro-field">Video publication window<select onchange="cwFilter(\'days\',this.value)">'+[[0,'All cached dates'],[7,'Last 7 days'],[30,'Last 30 days'],[90,'Last 90 days']].map(([id,label])=>'<option value="'+id+'" '+(id===CW.days?'selected':'')+'>'+label+'</option>').join('')+'</select></label><label class="pro-field">Video format<select onchange="cwFilter(\'format\',this.value)">'+[['all','All formats'],['long','Long videos'],['short-duration','Short duration']].map(([id,label])=>'<option value="'+id+'" '+(id===CW.format?'selected':'')+'>'+label+'</option>').join('')+'</select></label><button class="go" onclick="cwCompare(true)" '+(!w||CW.refreshing||CW.mutation?'disabled':'')+'>'+(CW.refreshing&&CW.refreshKey===key?'Refreshing public data…':CW.refreshing?'Refresh in progress…':'Refresh public data')+'</button></section>'}
function cwFilter(key,value){CW[key]=key==='days'?Number(value):value;CW.profile='';cwCompare()}
async function cwCompare(refresh=false){if(refresh&&(CW.refreshing||CW.mutation))return;const token=RTN,request=++CW.request;$('#main').innerHTML=proHeading('STUDY & COMPARE','Competitors','Your channel and up to 10 rivals. Compare real public data, not guessed performance.')+cwCompareControls()+'<div id="cw-comparison-result" aria-busy="true">'+skelGrid(2)+'</div>';try{await cwList();if(!cwValid(token,'compare',request))return;const w=cwCurrent();nav();topbar();if(!w){CW.compare=null;CW.compareKey='';cwCompareDraw();return}const key=cwComparisonKey(),cached=CW.compareCache.get(key),fetchId=++CW.compareRequest;CW.compare=cached||null;CW.compareKey=key;CW.compareError='';if(refresh){CW.refreshing=true;CW.refreshKey=key}cwCompareDraw(true);try{const data=await cwApi('compare',{id:w.id,refresh:!!refresh,days:CW.days,format:CW.format});if(fetchId===CW.compareRequest)CW.compareCache.set(key,data);if(!cwValid(token,'compare',request)||key!==cwComparisonKey()||fetchId!==CW.compareRequest)return;CW.compare=data;CW.profile=cwPickProfile(data);CW.compareError='';if(refresh)CW.feed=null}catch(e){if(cwValid(token,'compare',request)&&key===cwComparisonKey()&&fetchId===CW.compareRequest)CW.compareError='Could not '+(refresh?'refresh public data':'read the cached comparison')+': '+e.message+(cached?' Last cached results are shown below.':' No successful comparison is available.')}finally{if(refresh){CW.refreshing=false;CW.refreshKey=''}if(cwValid(token,'compare',request)&&key===cwComparisonKey())cwCompareDraw();else if(view==='compare'&&CW.compareKey===cwComparisonKey())cwCompareDraw()}}catch(e){if(cwValid(token,'compare',request))$('#main').innerHTML=proHeading('STUDY & COMPARE','Competitors','Workspace data could not be loaded.')+'<div class="card"><p role="alert">'+sx(e.message)+'</p><button onclick="cwCompare()">Retry cached comparison</button></div>'}}
function cwPickProfile(data){const profiles=data?.profiles||[];if(profiles.some(p=>p.channel?.id===CW.profile))return CW.profile;return (profiles.find(p=>p.role==='own')||profiles[0])?.channel?.id||''}
function cwProfile(id){CW.profile=id;cwCompareDraw();$('#cw-profile-select')?.focus()}
function cwChange(change){return change?.value==null?'Unavailable'+(change?.reason?' · '+change.reason:''):(change.value>0?'+':'')+sn(change.value)}
function cwComparisonRows(data){const w=cwCurrent(),profiles=(data?.profiles||[]).slice();if(w&&!profiles.some(p=>p.role==='own'))profiles.unshift({role:'own',channel:{id:w.youtube_id||'',name:w.name},summary:{},changes:{},unlinked:!w.youtube_id});return profiles}
function cwComparisonTable(data){const profiles=cwComparisonRows(data);return '<div class="studio-scroll cw-comparison-scroll" role="region" aria-label="Public channel comparison table, scroll horizontally" tabindex="0"><table class="studio-table cw-comparison-table"><caption>Public channel totals and sampled uploads · '+sx(cwCurrent()?.name||'')+'</caption><thead><tr>'+['Channel / role','Public lifetime views','Public subscribers','Public videos','Sample videos','Median sampled views','Weighted engagement','Uploads / week','Observed 24h views','Observed 7d views','Cached reading'].map(label=>'<th scope="col">'+label+'</th>').join('')+'</tr></thead><tbody>'+profiles.map(p=>{const c=p.channel||{},s=p.summary||{};return '<tr><th scope="row"><b>'+sx(c.name||c.id||'Unavailable')+'</b><small>'+sx(cwRole(p.role))+'</small>'+(p.unlinked?'<small>Not linked · no owner metrics</small>':'')+'</th><td>'+sn(c.views)+'</td><td>'+sn(c.subscribers)+'</td><td>'+sn(c.videos)+'</td><td>'+sn(s.sample)+'</td><td>'+sn(s.median_views)+'</td><td>'+(s.engagement_rate==null?'—':sn(s.engagement_rate)+'%')+'<small>'+sn(s.complete_engagement_videos)+' complete-count videos</small></td><td>'+sn(s.uploads_per_week)+'</td><td>'+sx(cwChange(p.changes?.['24h']))+'</td><td>'+sx(cwChange(p.changes?.['7d']))+'</td><td>'+sx(cwTimestamp(p.last_at))+'<small>'+sx(cwAge(p.last_at))+'</small></td></tr>'}).join('')+'</tbody></table></div>'}
function cwCompareDraw(loading=false){if(view!=='compare')return;const w=cwCurrent(),data=CW.compareKey===cwComparisonKey()?CW.compare:null,profiles=data?.profiles||[];CW.profile=cwPickProfile(data);const selected=profiles.find(p=>p.channel?.id===CW.profile),rows=selected?.rows||[],visible=CW.videoMode==='outliers'?rows.filter(v=>v.multiplier!=null&&v.multiplier>=2):rows;$('#main').innerHTML=proHeading('STUDY & COMPARE','Competitors','Your channel and up to 10 rivals. Public totals and sampled videos stay clearly separated.','<button onclick="go(\'channels\')">Manage competitors</button>')+cwCompareControls()+'<div class="cw-comparison-policy"><span class="studio-chip">Cached local reads by default</span><p>Refresh explicitly reads public YouTube data sequentially (about 3 reads per linked channel). No automatic cloud AI. Short-duration filters are not proof of Shorts-feed placement.</p></div>'+(CW.compareError?'<div class="cw-message error" role="alert">'+sx(CW.compareError)+'</div>':'')+'<section id="cw-comparison-result" aria-live="polite" aria-busy="'+loading+'">'+(!w?sempty('Create a channel workspace first','A draft is enough to start. Add competitors in My channels.')+'<button class="go" onclick="go(\'channels\')">Create your workspace</button>':(loading?'<p class="cw-loading" role="status">'+(CW.refreshing&&CW.refreshKey===cwComparisonKey()?'Refreshing linked channels one at a time. Existing cached results stay visible.':'Reading the local cached comparison…')+'</p>':'')+'<div class="cw-comparison-heading"><div><h2>'+sx(w.name)+'</h2><span class="studio-muted">'+cwCount(w)+' / '+cwLimit+' competitors'+(!w.youtube_id?' · Unlinked owner workspace':'')+'</span></div><div class="bar"><button class="sm" onclick="cwExport(\'csv\')" '+(!data?'disabled':'')+'>Export CSV</button><button class="sm" onclick="cwExport(\'json\')" '+(!data?'disabled':'')+'>Export JSON</button></div></div>'+(!w.youtube_id?snote('Your workspace is not linked to YouTube. Owner metrics are unavailable; cached competitors can still be inspected.'):'')+(data?'<div class="card cw-comparison-card">'+cwComparisonTable(data)+'</div><p class="cw-source-note"><b>Source:</b> '+sx(data.source||'Local cached public channel data')+' · Response: '+sx(cwTimestamp(data.fetched_at))+' · Per-channel reading dates are in the table.</p>'+(data.note?snote(data.note):'')+(data.warnings?.length?'<div class="cw-message" role="status">'+data.warnings.map(x=>sx(typeof x==='string'?x:JSON.stringify(x))).join('<br>')+'</div>':'')+proNotice('How these figures should be interpreted','Channel totals are public lifetime counters. Median views and uploads per week describe only the sampled and filtered uploads. Weighted engagement uses combined likes + comments divided by combined views on videos with complete counts, not an average of video percentages. Observed changes require recorded interval baselines; unavailable changes are not zero. Compare publication ages and formats before interpreting a multiplier. A baseline under 10 videos is labelled a small sample; sample size alone is not statistical confidence.')+'<section class="cw-profile-section"><div class="pro-section-heading"><div><h2>Inspect the videos behind the comparison</h2><p>Selecting a profile does not change your own channel workspace.</p></div></div><div class="cw-profile-controls"><label class="pro-field">Channel profile<select id="cw-profile-select" onchange="cwProfile(this.value)" '+(!profiles.length?'disabled':'')+'>'+(profiles.length?profiles.map(p=>'<option value="'+sx(p.channel?.id)+'" '+(p.channel?.id===CW.profile?'selected':'')+'>'+sx(p.channel?.name||p.channel?.id)+' · '+sx(cwRole(p.role))+'</option>').join(''):'<option>No cached profiles</option>')+'</select></label><label class="pro-field">Show videos<select onchange="CW.videoMode=this.value;cwCompareDraw()"><option value="outliers" '+(CW.videoMode==='outliers'?'selected':'')+'>Outliers · at least 2×</option><option value="all" '+(CW.videoMode==='all'?'selected':'')+'>All sampled videos</option></select></label></div>'+(selected?'<div class="cw-profile-metrics">'+smetric('Sampled videos',sn(selected.summary?.sample),'Chosen publication and format filters')+smetric('Median views / day',sn(selected.summary?.median_views_per_day),'Lifetime views ÷ video age')+smetric('Cached reading',cwTimestamp(selected.last_at),cwAge(selected.last_at))+'</div>':'')+(visible.length?cwVideoCards(visible):sempty(CW.videoMode==='outliers'?'No recorded outliers in this profile':'No cached videos in this profile',CW.videoMode==='outliers'?'Switch to all sampled videos, adjust your filters, or explicitly refresh public data.':'Try another profile or explicitly refresh public data.'))+'</section>':(!loading?sempty('No cached comparison available','Use Refresh public data to collect linked channels, or add competitors in My channels.'):'') ))+'</section>'}
function cwExport(format){const data=CW.compareKey===cwComparisonKey()?CW.compare:null,w=cwCurrent();if(!data||!w)return;const context={id:w.id,name:w.name,youtube_id:w.youtube_id||null,competitor_count:cwCount(w)},filters={days:CW.days,format:CW.format};if(format==='json'){sdownload('clicklab-'+w.id+'-comparison.json',JSON.stringify({workspace:context,filters,...data},null,2),'application/json');return}const headers=['Workspace ID','Workspace name','Publication days','Format','Source','Response timestamp','Role','Channel ID','Channel name','Public lifetime views','Public subscribers','Public videos','Sample videos','Median sampled views','Weighted engagement (%)','Complete engagement videos','Uploads per week','Median views per day','Observed 24h views','24h unavailable reason','Observed 7d views','7d unavailable reason','Last reading'];const rows=(data.profiles||[]).map(p=>{const c=p.channel||{},s=p.summary||{};return [w.id,w.name,CW.days,CW.format,data.source,data.fetched_at,p.role,c.id,c.name,c.views,c.subscribers,c.videos,s.sample,s.median_views,s.engagement_rate,s.complete_engagement_videos,s.uploads_per_week,s.median_views_per_day,p.changes?.['24h']?.value,p.changes?.['24h']?.reason,p.changes?.['7d']?.value,p.changes?.['7d']?.reason,p.last_at]});sdownload('clicklab-'+w.id+'-comparison.csv',scsv([headers,...rows]),'text/csv')}
// Explicit route assignments are required: VW captured the legacy functions at boot.
VW.home={...VW.home,f:homev,t:'Dashboard',i:'layers'};
VW.channels={f:cwChannels,t:'My channels',i:'bars'};
VW.compare={f:cwCompare,t:'Competitors',i:'layers'};
VW.cmp.t='Topic & packaging';
